import React,{useEffect,useMemo,useState} from 'react';
import{createRoot}from'react-dom/client';
import{supabase}from'./supabase';
import{UserRound,ShieldCheck,ChevronRight,LogOut,PackageCheck,TrendingUp,FileSpreadsheet,CheckCircle2,Upload,CalendarDays,Target,AlertTriangle}from'lucide-react';
import*as XLSX from'xlsx';
import'./styles.css';
const fmt=n=>new Intl.NumberFormat('es-AR',{maximumFractionDigits:2}).format(Number(n||0));
const fechaAR=f=>{const [y,m,d]=String(f||'').split('-');return d&&m&&y?`${d}/${m}/${y}`:f};
const nombreMes=m=>['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'][m]||m;
const estadoColor=p=>p>130?{color:'#7030A0',texto:'Sobresaliente'}:p>=95?{color:'#00B050',texto:'Objetivo'}:p>=85?{color:'#FFF200',texto:'Atención',dark:true}:{color:'#FF0000',texto:'Bajo objetivo'};
const dur=s=>{const m=Math.round(Number(s||0)/60),h=Math.floor(m/60);return h?`${h} h ${String(m%60).padStart(2,'0')} min`:`${m} min`};
const normal=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]+/g,' ').trim().toUpperCase();
const nombreSaludo=s=>{const t=String(s||'').trim(),partes=t.split(',');return (partes.length>1?partes.slice(1).join(','):t).trim()||t};
function App(){const[session,setSession]=useState(null),[profile,setProfile]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session);setLoading(false)});const{data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>subscription.unsubscribe()},[]);useEffect(()=>{if(!session){setProfile(null);return}supabase.from('perfiles').select('*,empleados(*)').eq('auth_user_id',session.user.id).single().then(({data})=>setProfile(data))},[session]);if(loading)return <Center text="Cargando..."/>;if(!session)return <Login/>;if(!profile)return <Center text="Preparando perfil..."/>;return profile.rol==='administrador'?<Admin profile={profile}/>:<Personal profile={profile}/>}
function Center({text}){return <div className="center"><b>{text}</b></div>}
function Login(){const[role,setRole]=useState('personal'),[user,setUser]=useState(''),[pass,setPass]=useState(''),[err,setErr]=useState(''),[busy,setBusy]=useState(false);async function go(){setBusy(true);setErr('');const email=role==='personal'?`${user.trim()}@personal.local`:user.trim();const{error}=await supabase.auth.signInWithPassword({email,password:pass});if(error)setErr('Usuario o contraseña incorrectos.');setBusy(false)}return <div className="login"><section className="hero"><small>CD MERCADO CENTRAL</small><h1>Mi productividad,<br/><span>día a día.</span></h1><p>Clasificación manual, picking y control de errores en un solo lugar.</p></section><section className="form"><div className="box"><small>BIENVENIDO</small><h2>Ingresar</h2><div className="roles"><button className={role==='personal'?'active':''} onClick={()=>{setRole('personal');setUser('')}}><UserRound/>Personal</button><button className={role==='admin'?'active':''} onClick={()=>{setRole('admin');setUser('')}}><ShieldCheck/>Administrador</button></div><label>{role==='personal'?'Número de legajo':'Correo del administrador'}</label><input value={user} onChange={e=>setUser(e.target.value)}/><label>Contraseña</label><input type="password" value={pass} onChange={e=>setPass(e.target.value)} onKeyDown={e=>e.key==='Enter'&&go()}/>{err&&<div className="error">{err}</div>}<button className="primary" onClick={go} disabled={busy}>{busy?'Ingresando...':<>Ingresar <ChevronRight/></>}</button></div></section></div>}
function Header({profile}){return <header><div><b>Mi Productividad</b><small>CD Mercado Central · DPO</small></div><div className="headright"><span>{profile.rol==='administrador'?'Administrador':profile.empleados?.apellido_nombre}</span><button onClick={()=>supabase.auth.signOut()}><LogOut/></button></div></header>}
function Personal({profile}){const[mod,setMod]=useState('manual'),[periods,setPeriods]=useState([]),[period,setPeriod]=useState('');useEffect(()=>{supabase.from('periodos').select('*').eq('publicado',true).order('anio',{ascending:false}).order('mes',{ascending:false}).then(({data})=>{setPeriods(data||[]);if(data?.[0])setPeriod(data[0].id)})},[]);return <><Header profile={profile}/><main><div className="title"><small>PANEL PERSONAL</small><h1>Hola, {nombreSaludo(profile.empleados?.apellido_nombre)}</h1><p>Datos vinculados por persona y actividad</p><div className="period-box"><CalendarDays/><div><span>PERÍODO CONSULTADO</span><select value={period} onChange={e=>setPeriod(e.target.value)}>{periods.length?periods.map(p=><option key={p.id} value={p.id}>{nombreMes(p.mes)} {p.anio}</option>):<option>Sin períodos publicados</option>}</select></div></div></div><nav>{[['manual',PackageCheck,'Clasificación manual'],['picking',TrendingUp,'Picking'],['errores',AlertTriangle,'Errores']].map(([id,I,t])=><button key={id} className={mod===id?'sel':''} onClick={()=>setMod(id)}><I/>{t}</button>)}</nav>{period?<Modulo tipo={mod} periodo={period} profile={profile}/>:<Empty text="No hay períodos publicados todavía."/>}<MiCuenta/></main></>}
function MiCuenta(){const[abierto,setAbierto]=useState(false),[clave,setClave]=useState(''),[repetir,setRepetir]=useState(''),[mensaje,setMensaje]=useState(''),[busy,setBusy]=useState(false);async function guardar(){setMensaje('');if(clave.length<8)return setMensaje('La contraseña debe tener al menos 8 caracteres.');if(!/[A-Za-z]/.test(clave)||!/[0-9]/.test(clave))return setMensaje('La contraseña debe incluir al menos una letra y un número.');if(clave!==repetir)return setMensaje('Las contraseñas no coinciden.');setBusy(true);const{error}=await supabase.auth.updateUser({password:clave});if(error)setMensaje(`No se pudo cambiar: ${error.message}`);else{setMensaje('Contraseña actualizada correctamente.');setClave('');setRepetir('')}setBusy(false)}return <section className="account-panel panel"><button className="account-toggle" onClick={()=>setAbierto(!abierto)}><UserRound/>Mi cuenta · Cambiar contraseña</button>{abierto&&<div className="account-form"><p>La contraseña debe tener al menos 8 caracteres, una letra y un número.</p><div className="twocol"><div><label>Nueva contraseña</label><input type="password" value={clave} onChange={e=>setClave(e.target.value)} autoComplete="new-password"/></div><div><label>Repetir contraseña</label><input type="password" value={repetir} onChange={e=>setRepetir(e.target.value)} autoComplete="new-password"/></div></div>{mensaje&&<div className={mensaje.includes('correctamente')?'account-success':'error'}>{mensaje}</div>}<button className="primary account-save" onClick={guardar} disabled={busy}>{busy?'Guardando...':'Guardar nueva contraseña'}</button></div>}</section>}
function Modulo({tipo,periodo,profile}){const map={manual:'clasificacion_manual',picking:'picking'},[rows,setRows]=useState(null);useEffect(()=>{let active=true;setRows(null);if(tipo==='errores'){Promise.all([supabase.from('errores_gatera').select('*').eq('periodo_id',periodo).order('fecha',{ascending:false}),supabase.from('errores_voice').select('*').eq('periodo_id',periodo).order('fecha',{ascending:false})]).then(([g,v])=>{if(active)setRows({gatera:g.data||[],voice:v.data||[]})})}else{supabase.from(map[tipo]).select('*').eq('periodo_id',periodo).order('fecha',{ascending:false}).then(({data})=>{if(active)setRows(data||[])})}return()=>{active=false}},[tipo,periodo]);if(rows===null)return <Center text="Cargando información..."/>;if(tipo==='errores'){if(!rows||Array.isArray(rows)||!Array.isArray(rows.gatera)||!Array.isArray(rows.voice))return <Center text="Cargando errores..."/>;if(!rows.gatera.length&&!rows.voice.length)return <Empty text="Sin errores ni verificaciones registradas en este período."/>;return <ErroresVisual gatera={rows.gatera} voice={rows.voice} profile={profile}/>}if(!rows.length)return <Empty text="Sin actividad registrada en este período."/>;if(tipo==='manual')return <ManualVisual rows={rows} profile={profile}/>;return <PickingVisual rows={rows} profile={profile}/>}
function Cumplimiento({value}){const e=estadoColor(value);return <span className="cumple" style={{background:e.color,color:e.dark?'#403500':'#fff'}}>{value.toFixed(1)}%</span>}
function Kpi({icon:Icon,label,value,sub,color}){return <div className="kpi" style={{borderColor:color}}><div className="kpi-icon" style={{color,background:`${color}18`}}><Icon/></div><span>{label}</span><b>{value}</b><small>{sub}</small></div>}
function BarraTarget({productividad,target}){const max=Math.max(productividad,target)*1.15,e=estadoColor(productividad/target*100);return <div className="target-wrap"><div className="target-labels"><span>Target {fmt(target)}</span><span>Productividad {fmt(productividad)}</span></div><div className="target-track"><i style={{left:`${Math.min(98,target/max*100)}%`}}/><em style={{width:`${Math.min(100,productividad/max*100)}%`,background:e.color}}/></div></div>}
function ManualVisual({rows,profile}){const fechas=useMemo(()=>[...new Set(rows.map(r=>r.fecha).filter(Boolean))].sort((a,b)=>b.localeCompare(a)),[rows]),[dia,setDia]=useState('mes');useEffect(()=>setDia('mes'),[rows]);const orden=(dia==='mes'?rows:rows.filter(r=>r.fecha===dia)).slice().sort((a,b)=>b.fecha.localeCompare(a.fecha)),target=4.6,objTotal=orden.reduce((a,r)=>a+Number(r.objetivo||0),0),realTotal=orden.reduce((a,r)=>a+Number(r.real||0),0),resultado=objTotal?target*realTotal/objTotal:0,cum=objTotal?realTotal/objTotal*100:0,e=estadoColor(cum);return <><div className="module-head errors-head"><div><h2>Clasificación manual</h2><p>{profile.empleados?.apellido_nombre}</p></div><label className="day-filter"><span>VISTA</span><select value={dia} onChange={e=>setDia(e.target.value)}><option value="mes">Todo el mes</option>{fechas.map(f=><option key={f} value={f}>{fechaAR(f)}</option>)}</select></label></div><div className="manual-kpi-grid"><Kpi icon={Target} label="TARGET" value="4,6" sub="Paletas por hora-hombre" color="#FFC000"/><Kpi icon={PackageCheck} label={dia==='mes'?"RESULTADO DEL MES":"RESULTADO DEL DÍA"} value={fmt(resultado)} sub={dia==='mes'?'Consolidado mensual':fechaAR(dia)} color="#006600"/><Kpi icon={TrendingUp} label="CUMPLIMIENTO" value={`${cum.toFixed(1)}%`} sub={e.texto} color={e.color}/><Kpi icon={CalendarDays} label="DÍAS REGISTRADOS" value={new Set(orden.map(r=>r.fecha)).size} sub={dia==='mes'?'Jornadas del período':'Fecha seleccionada'} color="#D1A33C"/></div><section className="panel detail manual-detail"><h3>{dia==='mes'?'Detalle día por día':`Detalle del ${fechaAR(dia)}`}</h3><div className="scroll"><table><thead><tr>{['Fecha','Objetivo','Real','Diferencia','Resultado','Target','Cumplimiento'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{orden.map(r=>{const res=Number(r.objetivo)?target*Number(r.real)/Number(r.objetivo):0,por=Number(r.objetivo)?Number(r.real)/Number(r.objetivo)*100:0;return <tr key={r.id}><td><b>{fechaAR(r.fecha)}</b></td><td>{fmt(r.objetivo)}</td><td><b>{fmt(r.real)}</b></td><td>{fmt(r.diferencia)}</td><td><b>{fmt(res)}</b></td><td>4,6</td><td><Cumplimiento value={por}/></td></tr>})}</tbody></table></div></section></>}
function ErroresVisual({gatera,voice,profile}){const fechas=useMemo(()=>[...new Set([...gatera,...voice].map(r=>r.fecha).filter(Boolean))].sort((a,b)=>b.localeCompare(a)),[gatera,voice]),[dia,setDia]=useState('mes');useEffect(()=>setDia('mes'),[gatera,voice]);const gf=dia==='mes'?gatera:gatera.filter(r=>r.fecha===dia),vf=dia==='mes'?voice:voice.filter(r=>r.fecha===dia),voiceErrores=vf.filter(r=>Number(r.total_errores||0)>0),incGatera=gf.length,incVoice=voiceErrores.length,totalIncidencias=incGatera+incVoice,sinNovedad=vf.filter(r=>Number(r.total_errores||0)===0).length,faltG=gf.filter(r=>normal(r.motivo).includes('FALT')).length,sobG=gf.filter(r=>normal(r.motivo).includes('SOBR')).length,cambG=gf.filter(r=>normal(r.motivo).includes('SABOR')||normal(r.motivo).includes('CAMBIO')).length,otrosG=Math.max(0,incGatera-faltG-sobG-cambG),faltV=voiceErrores.filter(r=>Number(r.faltantes||0)>0).length,sobV=voiceErrores.filter(r=>Number(r.sobrantes||0)>0).length,cambV=voiceErrores.filter(r=>Number(r.cambio_sabor||0)>0).length,otrosV=Math.max(0,incVoice-faltV-sobV-cambV),detalle=[...gf.map(r=>({id:`g-${r.id}`,fecha:r.fecha,origen:'Gatera',cancha:r.cancha,motivo:r.motivo,cantidad:r.cantidad,referencia:r.sku||r.paleta||'',comentario:r.comentario||''})),...voiceErrores.map(r=>({id:`v-${r.id}`,fecha:r.fecha,origen:'Voice Picking',cancha:r.cancha,motivo:r.motivo||'Error sin motivo',cantidad:r.total_errores,referencia:r.numero_paleta?`Paleta ${r.numero_paleta}`:'',comentario:''}))].sort((a,b)=>b.fecha.localeCompare(a.fecha));return <><div className="module-head errors-head"><div><h2>Errores</h2><p>Consolidado de Gatera y Voice Picking · {profile.empleados?.apellido_nombre}</p></div><label className="day-filter"><span>VISTA</span><select value={dia} onChange={e=>setDia(e.target.value)}><option value="mes">Todo el mes</option>{fechas.map(f=><option key={f} value={f}>{fechaAR(f)}</option>)}</select></label></div><div className="errors-kpi-grid"><Kpi icon={AlertTriangle} label="TOTAL DE INCIDENCIAS" value={fmt(totalIncidencias)} sub={dia==='mes'?'Total del mes':fechaAR(dia)} color="#B40000"/><Kpi icon={FileSpreadsheet} label="INCIDENCIAS EN GATERA" value={fmt(incGatera)} sub="Registros del período" color="#FF6A00"/><Kpi icon={ShieldCheck} label="INCIDENCIAS VOICE PICKING" value={fmt(incVoice)} sub={`${sinNovedad} paletas sin novedad`} color="#00A651"/><Kpi icon={CheckCircle2} label="ESTADO" value={totalIncidencias?'Con novedades':'Sin errores'} sub={dia==='mes'?'Período mensual':'Fecha seleccionada'} color={totalIncidencias?'#E7CE00':'#087A16'}/></div><div className="error-source-grid"><section className="panel source-card gatera-source"><h3>Gatera</h3><p><b>{fmt(incGatera)}</b> incidencias registradas</p><small>Faltantes: {fmt(faltG)} · Sobrantes: {fmt(sobG)} · Cambios de sabor: {fmt(cambG)}{otrosG?` · Otros: ${fmt(otrosG)}`:''}</small></section><section className="panel source-card voice-source"><h3>Voice Picking</h3><p><b>{fmt(incVoice)}</b> incidencias detectadas</p><small>Sin novedad: {sinNovedad} · Faltantes: {fmt(faltV)} · Sobrantes: {fmt(sobV)} · Cambios de sabor: {fmt(cambV)}{otrosV?` · Sin motivo/otros: ${fmt(otrosV)}`:''}</small></section></div><section className="panel detail errors-detail"><h3>Detalle {dia==='mes'?'del mes':`del ${fechaAR(dia)}`}</h3><p className="detail-sub">Cada fila representa una incidencia; la columna Cantidad muestra los bultos involucrados.</p>{detalle.length?<div className="scroll"><table><thead><tr>{['Fecha','Origen','Cancha','Motivo','Cantidad','Referencia','Comentario'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{detalle.map(r=><tr key={r.id}><td><b>{fechaAR(r.fecha)}</b></td><td><span className={`origen ${r.origen==='Gatera'?'gatera':'voice'}`}>{r.origen}</span></td><td><b>{r.cancha}</b></td><td>{r.motivo}</td><td><b>{fmt(r.cantidad)}</b></td><td>{r.referencia}</td><td>{r.comentario}</td></tr>)}</tbody></table></div>:<div className="no-errors-day"><CheckCircle2/><b>Sin errores registrados en {dia==='mes'?'este período':'la fecha seleccionada'}.</b></div>}</section></>}
function GateraVisual({rows,profile}){const faltantes=rows.filter(r=>normal(r.motivo).includes('FALTANTE')).reduce((a,r)=>a+Number(r.cantidad||0),0),sobrantes=rows.filter(r=>normal(r.motivo).includes('SOBRANTE')).reduce((a,r)=>a+Number(r.cantidad||0),0),orden=[...rows].sort((a,b)=>b.fecha.localeCompare(a.fecha));return <><div className="module-head"><h2>Errores detectados en gatera</h2><p>{profile.empleados?.apellido_nombre}</p></div><div className="gatera-kpi-grid"><Kpi icon={FileSpreadsheet} label="TOTAL DE REGISTROS" value={rows.length} sub="Errores asociados al operario" color="#B40000"/><Kpi icon={PackageCheck} label="FALTANTES" value={fmt(faltantes)} sub="Bultos informados" color="#FF1F2D"/><Kpi icon={PackageCheck} label="SOBRANTES" value={fmt(sobrantes)} sub="Bultos informados" color="#FF6A00"/></div><section className="panel detail gatera-detail"><h3>Detalle del mes</h3><p className="detail-sub">Fecha, cancha, motivo, cantidad y observación</p><div className="scroll"><table><thead><tr>{['Fecha','Cancha','Motivo','Cantidad','SKU','Comentario'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{orden.map(r=><tr key={r.id}><td><b>{fechaAR(r.fecha)}</b></td><td><b>{r.cancha}</b></td><td><span className={`motivo ${normal(r.motivo).includes('SOBRANTE')?'sobrante':'faltante'}`}>{r.motivo}</span></td><td><b>{fmt(r.cantidad)}</b></td><td>{r.sku}</td><td>{r.comentario}</td></tr>)}</tbody></table></div></section></>}
function VoiceVisual({rows,profile}){const sin=rows.filter(r=>Number(r.total_errores||0)===0).length,errores=rows.reduce((a,r)=>a+Number(r.total_errores||0),0),falt=rows.reduce((a,r)=>a+Number(r.faltantes||0),0),sob=rows.reduce((a,r)=>a+Number(r.sobrantes||0),0),camb=rows.reduce((a,r)=>a+Number(r.cambio_sabor||0),0),conError=rows.filter(r=>Number(r.total_errores||0)>0).sort((a,b)=>b.fecha.localeCompare(a.fecha));return <><div className="module-head"><h2>Errores de Voice Picking</h2><p>Detectados por el verificador · {profile.empleados?.apellido_nombre}</p></div><div className="voice-kpi-grid"><Kpi icon={CheckCircle2} label="PALETAS SIN NOVEDAD" value={sin} sub="Verificaciones sin error" color="#087A16"/><Kpi icon={ShieldCheck} label="ERRORES DETECTADOS" value={fmt(errores)} sub="Durante la verificación" color="#00B85A"/><Kpi icon={TrendingUp} label="ESTADO MENSUAL" value={errores?'Con novedades':'Sin errores'} sub="Acumulado visible" color="#E7CE00"/></div><section className="voice-summary panel"><div className={`voice-status ${errores?'warn':''}`}><CheckCircle2/><div><h3>{errores?'Errores detectados por el verificador':'Sin errores detectados por el verificador'}</h3><p>Faltantes: {fmt(falt)} · Sobrantes: {fmt(sob)} · Cambios de sabor: {fmt(camb)}</p><small>Este control se muestra separado de los errores informados en gatera.</small></div></div>{conError.length>0&&<div className="scroll voice-table"><table><thead><tr>{['Fecha','Cancha','Paleta','Bultos','Motivo','Errores'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{conError.map(r=><tr key={r.id}><td><b>{fechaAR(r.fecha)}</b></td><td>{r.cancha}</td><td>{r.numero_paleta}</td><td>{fmt(r.bultos)}</td><td>{r.motivo}</td><td><b>{fmt(r.total_errores)}</b></td></tr>)}</tbody></table></div>}</section></>}
function PickingVisual({rows,profile}){const dias=useMemo(()=>{const g={};rows.forEach(r=>{if(!g[r.fecha])g[r.fecha]={fecha:r.fecha,packs:0,pallets:0,segundos:0,targetPeso:0,items:[]};const d=g[r.fecha];d.packs+=Number(r.packs||0);d.pallets+=Number(r.pallets||0);d.segundos+=Number(r.duracion_segundos||0);d.targetPeso+=Number(r.target||0)*Number(r.duracion_segundos||0);d.items.push(r)});return Object.values(g).map(d=>({...d,productividad:d.segundos?d.packs/(d.segundos/3600):0,target:d.segundos?d.targetPeso/d.segundos:0})).sort((a,b)=>b.fecha.localeCompare(a.fecha))},[rows]),[dia,setDia]=useState('mes');useEffect(()=>setDia('mes'),[rows]);const visibles=dia==='mes'?dias:dias.filter(d=>d.fecha===dia),packs=visibles.reduce((a,d)=>a+d.packs,0),segundos=visibles.reduce((a,d)=>a+d.segundos,0),targetPeso=visibles.reduce((a,d)=>a+d.targetPeso,0),productividad=segundos?packs/(segundos/3600):0,target=segundos?targetPeso/segundos:0,cum=target?productividad/target*100:0,e=estadoColor(cum);return <><div className="module-head errors-head"><div><h2>Picking</h2><p>{profile.empleados?.apellido_nombre} · Turno {profile.empleados?.turno} · Varias canchas</p></div><label className="day-filter"><span>VISTA</span><select value={dia} onChange={e=>setDia(e.target.value)}><option value="mes">Todo el mes</option>{dias.map(d=><option key={d.fecha} value={d.fecha}>{fechaAR(d.fecha)}</option>)}</select></label></div><div className="kpi-grid"><Kpi icon={TrendingUp} label={dia==='mes'?"PRODUCTIVIDAD DEL MES":"PRODUCTIVIDAD DEL DÍA"} value={`${fmt(productividad)} bultos/h`} sub={`${fmt(packs)} packs ÷ ${dur(segundos)}`} color="#006600"/><Kpi icon={Target} label="TARGET PONDERADO" value={`${fmt(target)} bultos/h`} sub="Según el tiempo trabajado en cada cancha" color="#FFC000"/><Kpi icon={CheckCircle2} label="CUMPLIMIENTO" value={`${cum.toFixed(1)}%`} sub={`${fmt(productividad)} ÷ ${fmt(target)} · ${e.texto}`} color={e.color}/></div><section className="daily panel"><h3>{dia==='mes'?'Resultado día por día':`Resultado del ${fechaAR(dia)}`}</h3><p>{dia==='mes'?'El consolidado se calcula con packs totales ÷ horas totales trabajadas.':'Productividad consolidada: packs totales ÷ tiempo total trabajado. No es el promedio simple entre canchas.'}</p>{visibles.map(d=>{const dc=d.target?d.productividad/d.target*100:0;return <article className="day" key={d.fecha}><div className="day-head"><div><b>{fechaAR(d.fecha)}</b><small>Total del día: {fmt(d.packs)} packs · {fmt(d.pallets)} pallets · {dur(d.segundos)} · Target ponderado {fmt(d.target)}</small></div><div><strong>{fmt(d.productividad)} bultos/h</strong><Cumplimiento value={dc}/></div></div>{d.items.map(r=>{const c=Number(r.target)?Number(r.productividad)/Number(r.target)*100:0;return <div className="activity" key={r.id}><div className="activity-main"><div><b className="court">{r.cancha}</b><small>{fmt(r.packs)} packs · {fmt(r.pallets)} pallets · {dur(r.duracion_segundos)}</small></div><div className="activity-result"><strong>{fmt(r.productividad)} bultos/h</strong><span>Target {fmt(r.target)}</span><Cumplimiento value={c}/></div></div><BarraTarget productividad={Number(r.productividad)} target={Number(r.target)}/></div>})}</article>})}</section><section className="panel detail"><h3>Detalle por actividad</h3><div className="scroll"><table><thead><tr>{['Fecha','Cancha','Packs','Pallets','Duración','Bultos/hora','Target','Cumplimiento'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{visibles.flatMap(d=>d.items).map(r=><tr key={r.id}><td><b>{fechaAR(r.fecha)}</b></td><td><b>{r.cancha}</b></td><td>{fmt(r.packs)}</td><td>{fmt(r.pallets)}</td><td>{dur(r.duracion_segundos)}</td><td><b>{fmt(r.productividad)}</b></td><td>{fmt(r.target)}</td><td><Cumplimiento value={Number(r.target)?Number(r.productividad)/Number(r.target)*100:0}/></td></tr>)}</tbody></table></div></section></>}
function Empty({text}){return <div className="empty"><CheckCircle2/><h3>{text}</h3></div>}
